use std::{fs,path::Path,collections::BTreeMap,os::unix::fs::FileTypeExt,io::Read};use sha2::{Digest,Sha256};use serde_json::{Value,json};
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy(src:&Path,dst:&Path,root:&Path,index:&mut BTreeMap<String,String>){if src.is_dir(){fs::create_dir_all(dst).unwrap();for e in fs::read_dir(src).unwrap(){let p=e.unwrap().path();copy(&p,&dst.join(p.file_name().unwrap()),root,index);}return;}let kind=src.symlink_metadata().unwrap().file_type();if kind.is_fifo(){assert!(src.file_name().is_some_and(|s|s=="ctl"||s=="ack"));return;}assert!(kind.is_file());fs::copy(src,dst).unwrap();let h=hash(src);assert_eq!(hash(dst),h);assert!(index.insert(dst.strip_prefix(root).unwrap().to_str().unwrap().into(),h).is_none());}
fn main(){let r=Path::new("/tmp/zopro-front-end-counters");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-front-end-counters");let analysis:Value=serde_json::from_slice(&fs::read(r.join("analysis.json")).unwrap()).unwrap();assert_eq!(analysis["status"],"closed_verified");let pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(r.join("closeout-pins.json")).unwrap()).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h,"closingpin{p}");}let dst=report.join("artifacts");assert!(!dst.exists());fs::create_dir(&dst).unwrap();let mut index=BTreeMap::new();for n in["experiment.json","availability-work.rs","prepare.rs","host.json","event-definitions.json","prior-proof-sha256.json","prior-proof-audit.json","capture-order.json","capture-template.json","input-pins.json","availability-plan.json","availability.log","availability-check.json","capture-pins.json","capture-plan.json","capture.log","analyze.rs","analyze-initial.rs","analysis-parser-repair.json","rows.json","proof-inventory.json","analysis.json","closeout-pins.json","next-design.md","write-report.rs","publish.rs"]{copy(&r.join(n),&dst.join(n),&dst,&mut index);}for n in["counter-sources","availability","capture","counter-data","proofs"]{copy(&r.join(n),&dst.join(n),&dst,&mut index);}let members=index.keys().filter(|n|n.ends_with(".proof")||n.ends_with(".public")).count();assert_eq!(members,54);fs::write(dst.join("SHA256SUMS"),index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();fs::write(dst.join("artifact-index.json"),serde_json::to_vec_pretty(&json!({"files":index.len(),"sha256":index,"new_proof_public_members":members,"new_distinct_gnark_exports":27,"compiled_availability_work_sha256":hash(r.join("availability-work")),"executables_and_caches_not_copied":true,"final_input_and_receipt_pins_rehashed":pins.len(),"no_raw_perf_sampling_files":true,"source":"Exact accepted SDK; unchanged170productionfiles","scope":"Complete dispatch-counter diagnostic; no performance adoption"})).unwrap()).unwrap();fs::write(report.join(".gitattributes"),"artifacts/** -whitespace\n").unwrap();println!("Published{}hashedartifacts54proof/publicmembers,{}closingpinsverified",index.len(),pins.len());}
